    return 5.0 + 2.0 * int(kg)

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
        else:
            stack.append(char)
    return not stack

def roman_to_int(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        current_value = roman[char]
        if current_value < prev_value:
            total -= current_value
        else:
            total += current_value
        prev_value = current_value
    return total

def c_to_f(c: float) -> float:
    f = c * 9 / 5 + 32
    return round(f, 1)

def run_length_encode(s: str) -> str:
    if not s:
        return ''
    result = []
    current_char = s[0]
    count = 1
    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f'{current_char}{count}')
            current_char = char
            count = 1
    result.append(f'{current_char}{count}')
    return ''.join(result)

def chunk(xs: list, k: int) -> list:
    result = []
    for i in range(0, len(xs), k):
        result.append(xs[i:i+k])
    return result

